import{CanonicalWorld}from'../../../world/service.mjs';
import{SpeciesCatalogService}from'../../../species-catalog-service.mjs';
import{createCanonicalCreature,canonicalHp}from'../../../canonical-session.mjs';
import{createBattleRules,calculateDamage}from'../../../battle-v3/rules.mjs';
import{positionCell,pointDistance}from'../../../world/definition.mjs';
import{stableJSON}from'../../../compatibility/codec.mjs';
const EVENTS=Object.freeze(['P00_HOME_START','P01_ECO_CENTER','P02_FIRST_PARTNER','RIVAL_00','P03_TUTORIAL','P04_SUSPICIOUS_TRACE']),TARGET='route:PROLOGUE:S1';
/** DEV preparation only. Always executes original actions itself; accepts no runtime, coordinates, results or flags. */
export async function runOriginalEarlyStreamJourney({adapter,signal}={}){
 const check=()=>{if(signal?.aborted)throw Object.assign(Error('EARLY_STREAM_PREPARATION_ABORTED'),{code:'PRESENTATION_DISPOSED'})},tick=async()=>{check();await new Promise(r=>setTimeout(r,0));check()};check();
 const catalog=new SpeciesCatalogService({namespace:'canonical',adapter}),rules=createBattleRules(adapter),actions=[],receipts=[];let w,battles=0,partyFixture=null;
 const driver=async b=>{battles++;for(let i=0;i<512;i++){await tick();const s=b.snapshot();if(s.phase==='ended'){if(s.outcome!=='won')throw Error('EARLY_SOURCE_BATTLE_LOST');return s}if(s.phase==='forced-switch'){b.act({type:'switch',index:s.party.findIndex(p=>p.hp>0)});continue}const mon=s.party[s.active],enemy=s.opponents[s.enemyActive],moves=mon.moves.filter(m=>m.pp>0),score=id=>{const move=rules.moves[id];return move.power?calculateDamage({rules,catalog,move,attacker:mon,defender:enemy,critical:false,randomPercent:100}).damage:0};moves.sort((a,b)=>score(b.id)-score(a.id));b.act({type:'move',moveId:moves[0]?.id??'SYSTEM_STRUGGLE'})}throw Error('EARLY_SOURCE_BATTLE_BOUND')};
 const make=runtime=>new CanonicalWorld({adapter,mode:'test',...(runtime?{runtime}:{}),rng:()=>.4,battleDriver:driver,hooks:{dialogue:async()=>check()},persist:async next=>{check();receipts.push(structuredClone(next))}});
 const untouched=s=>!s.progress.completedEvents.includes('S1_WATER_DECLINE')&&!s.progress.defeatedTrainers.includes('ROUTE_S1_01')&&!s.progress.defeatedTrainers.includes('ROUTE_S1_07');
 try{w=make();for(const id of EVENTS){await tick();if(!w.story.eventAvailable(id))throw Error('EARLY_EVENT_PREDECESSOR');await w.story.runEvent(id,{battleDriver:driver,rng:()=>.4});actions.push({kind:'event',id,revision:w.snapshot().revision});if(id==='P02_FIRST_PARTNER'){const before=w.snapshot(),next=structuredClone(before);next.party=[createCanonicalCreature(catalog,next.starterId,100)];partyFixture={speciesId:next.starterId,level:100,hp:next.party[0].hp,maxHP:canonicalHp(catalog,next.starterId,100),label:'QA_INITIAL_PARTY_AFTER_ORIGINAL_PARTNER_NOT_NORMAL_DIFFICULTY'};if(next.party[0].hp!==partyFixture.maxHP)throw Error('QA_PARTY_NOT_MAX_HP');const a=structuredClone(next),b=structuredClone(before);delete a.party;delete b.party;if(stableJSON(a)!==stableJSON(b))throw Error('QA_NON_PARTY_MUTATION');w.dispose();w=make(next)}}
 if(battles!==1||!untouched(w.snapshot()))throw Error('EARLY_PRESTREAM_HISTORY');const row=w.definition.points[TARGET],start=positionCell(w.snapshot().position),map=w.definition.maps[w.snapshot().position.scene],queue=[[start.x,start.y]],seen=new Map([[`${start.x},${start.y}`,null]]);let goal=null;
 for(let i=0;i<queue.length&&!goal;i++){const[x,y]=queue[i];if(Math.abs(x-row.x)+Math.abs(y-row.y)<=1){goal=[x,y];break}for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,key=`${nx},${ny}`;if(nx<0||ny<0||nx>=map.width||ny>=map.height||seen.has(key)||!w.host.canOccupy(w.snapshot(),row.mapId,nx,ny))continue;seen.set(key,[x,y]);queue.push([nx,ny])}}
 if(!goal)throw Error('EARLY_CANONICAL_APPROACH');const path=[];for(let at=goal;seen.get(at.join(','));at=seen.get(at.join(',')))path.push(at);path.reverse();for(const[x,y]of path){await tick();const c=positionCell(w.snapshot().position),direction=x>c.x?'right':x<c.x?'left':y>c.y?'down':'up';if(!(await w.move(direction)).moved)throw Error('EARLY_CANONICAL_MOVE_BLOCKED')}
 const before=w.snapshot(),mark=receipts.length;await w.interact(TARGET);check();const after=w.snapshot(),accepted=receipts.slice(mark);if(accepted.length!==2||accepted[0].position.scene!=='world:hub:PROLOGUE'||!accepted[0].progress.completedStages.includes('PROLOGUE')||accepted[1].position.scene!=='world:hub:S1'||after.world.warps!==before.world.warps+1||after.world.routeLog.at(-1)?.warpId!==TARGET||!untouched(after))throw Error('EARLY_ORIGINAL_TWO_COMMIT_PROOF');
 return{runtime:after,sourceRow:structuredClone(row),receipts:accepted,report:{scope:'DEV_ORIGINAL_EARLY_S1_NO_USER_STORAGE',actions,originalBattles:battles,originalExitCommits:accepted.length,sourceWarp:TARGET,partyFixture,firstActionsUntouched:{resident:true,trainer01:true,trainer07:true},flagsWrittenByHelper:0,positionWrittenByHelper:0,battleResultsWrittenByHelper:0,ordinaryDifficulty:false}};
 }finally{w?.dispose()}
}
